<script setup lang="ts">
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElAlert, ElButton, ElCheckbox, ElForm, ElFormItem, ElInput } from 'element-plus'
const route = useRoute(); const router = useRouter(); const email = ref(''); const password = ref(''); const remember = ref(true); const error = ref('')
function submit() { error.value = ''; if (!email.value.trim()) { error.value = '请输入用户名或邮箱'; return } if (password.value.length < 6) { error.value = '密码至少需要 6 位'; return } const target = String(route.query.returnTo || '/console/dashboard'); router.push(target.startsWith('/console/') ? target : '/console/dashboard') }
</script>
<template><div class="login-page"><div class="login-decoration"><div class="login-orb one"></div><div class="login-orb two"></div><span>✦</span></div><main class="login-card"><div class="login-brand"><div class="brand-mark">i</div><div><strong>Ikaros</strong><small>Console</small></div></div><p class="eyebrow">安全访问</p><h1>欢迎回来</h1><p class="login-subtitle">登录你的 Ikaros 工作空间</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="用户名或邮箱"><el-input v-model="email" type="text" autocomplete="username" placeholder="name@example.com" /></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password autocomplete="current-password" placeholder="输入密码" /></el-form-item><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" /><div class="login-options"><el-checkbox v-model="remember">记住此设备</el-checkbox><el-button link @click="router.push('/recovery')">忘记密码？</el-button></div><el-button class="login-button" type="primary" native-type="submit">登录 <span>→</span></el-button></el-form><p class="login-footnote">首次使用？请联系工作空间管理员完成初始化。</p></main></div></template>
